head.script:
// 테스트 설명, 유효성 값 설정
//  - 본 샘플(_1) : 단일 Header 의 width 설정/미설정, 다른 영역(Body/Footer) width 무시, autoFit(allColumn, lastColumn), setColumnWidth 축
//  - 병합 Header 의 width 결정(같은 위치의 병합되지 않은 Header / Body) 항목은 column_P_width_2 소유
//  - WebSquare Studio 의 Drag&Drop 너비 조정 항목은 Studio 편집기 동작이라 런타임 검증 불가로 제외
scwin.tData = {
    "description" : "[column > P > width]<br/>Column 의 너비(Width)를 설정합니다.",
    "validation" : [
        "값(px) 설정 시, Column 의 너비를 픽셀(px) 단위 숫자로 설정합니다.",
        "Header Column 에 속성값을 설정하지 않으면 Column 의 너비가 0 으로 적용됩니다.",
        "Header Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다.",
        "autoFit='allColumn' : width 속성값의 비율을 유지하며 GridView 의 너비에 맞게 조정됩니다.",
        "autoFit='lastColumn' : 마지막 Column 의 너비가 GridView 의 남는 여백만큼 늘어납니다.",
        "setColumnWidth() 메소드로 실행 중에 Column 의 너비를 변경할 수 있습니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_width.setValue("200");
    con_otherWidth.setValue("");
    con_autoFit.setValue("");
    par_size.setValue("50");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// Header Column width 고정값 (name 은 con_width)
scwin.headerWidth = { "code" : "100", "name" : "", "qty" : "150", "memo" : "100" };



// comp 생성 (con 변경은 Target 재생성 버튼으로 반영)
//  - con_width      : name Header Column 의 width ('' / 120 / 200) -> validation 1, 2
//  - con_otherWidth : name Body, Footer Column 의 width ('' / 300) -> validation 2, 3 (Header 값만 적용되는지)
//  - con_autoFit    : GridView autoFit ('' / allColumn / lastColumn) -> validation 4, 5
//  - 나머지 Column 의 width 는 Header/Body/Footer 모두 같은 값 (no 60, code 100, qty 150, memo 100)
//  - 첫번째 Column(no) 은 너비 출력 대상 아님 : 첫번째 Column 은 화면 너비가 설정값보다 1px 작게 그려지므로 검증 Column 을 두번째부터 둠
//  - Column 너비 합계(60+100+200+150+100=610) < GridView 너비(640) : lastColumn 이면 memo 가 남는 여백만큼 늘어남
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cWidth = con_width.getValue();
    let cOtherWidth = con_otherWidth.getValue();
    let cAutoFit = con_autoFit.getValue();
    scwin.headerWidth["name"] = cWidth;

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 검증 대상은 name Column, GridView 너비 640px, Header Column width : no 60 / code 100 / qty 150 / memo 100\n[확인] Column 너비 확인 버튼으로 각 Column 의 화면 너비(괄호는 Header Column 의 width 속성값) 확인"', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // 바인딩 dataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="no" name="no" dataType="text"></w2:column>';
    strDlt += '<w2:column id="code" name="code" dataType="text"></w2:column>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="qty" name="qty" dataType="number"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "no" : "1", "code" : "P-1001", "name" : "무선 키보드", "qty" : 12, "memo" : "입고 대기" },
        { "no" : "2", "code" : "P-1002", "name" : "광마우스", "qty" : 30, "memo" : "정상" },
        { "no" : "3", "code" : "P-1003", "name" : "모니터 받침대", "qty" : 7, "memo" : "재고 부족" }
    ], false);

    // GridView 속성
    let attrGrid = (cAutoFit === '') ? '' : ' autoFit="' + cAutoFit + '"';

    // 검증 대상 name Column 의 width (Header / Body, Footer)
    let attrHeader = (cWidth === '') ? '' : ' width="' + cWidth + '"';
    let attrOther = (cOtherWidth === '') ? '' : ' width="' + cOtherWidth + '"';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:640px;height:150px;"' + attrGrid + '>';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="60" style="" inputType="text" id="column0" value="no"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="code"></w2:column>';
    strTarget += '<w2:column style="" inputType="text" id="column2" value="name"' + attrHeader + '></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="column3" value="qty"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column4" value="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="60" style="" inputType="text" id="no" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="code" value=""></w2:column>';
    strTarget += '<w2:column style="" inputType="text" id="name" value=""' + attrOther + '></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="qty" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="memo" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="60" style="" inputType="text" id="footer_no" value="합계"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="footer_code" value=""></w2:column>';
    strTarget += '<w2:column style="" inputType="text" id="footer_name" value=""' + attrOther + '></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="expression" id="footer_qty" expression="sum(\'qty\')"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="footer_memo" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 각 Column 의 화면 너비(Body 첫 Row Cell 기준, px) 문자열 : "Column : 화면 너비 (Header width 속성값)"
scwin.getColumnWidthText = function () {
    let arrName = ["code", "name", "qty", "memo"];
    let arr = [];
    for (let i = 0; i < arrName.length; i++) {
        let td = document.querySelector("[id='" + target1.id + "_cell_0_" + (i + 1) + "']");
        let hw = scwin.headerWidth[arrName[i]];
        arr.push(arrName[i] + " : " + (td ? td.offsetWidth : "-") + " (" + (hw === "" ? "미설정" : hw) + ")");
    }
    return arr.join(" / ");
}



// validation 1 ~ 5 판정 출력 : 각 Column 의 화면 너비
scwin.btn_checkColumnWidth_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("Column 너비 : " + scwin.getColumnWidthText());
}



// validation 6 판정 출력 : setColumnWidth('name', size) 실행 후 각 Column 너비
scwin.btn_setColumnWidth_onclick = function () {
    let size = Number(par_size.getValue());
    target1.setColumnWidth("name", size);
    wf_body_bottom.getObj("scwin").setReturnValue("setColumnWidth('name', " + size + ") -> Column 너비 : " + scwin.getColumnWidthText());
}
